insert into public.email_automations(id,key,name,trigger_type,is_active) values('48f08712-7146-54dc-ad58-e1dc6ae50879','course_month-health','Месяц здоровья','course',false) on conflict(id) do nothing;
insert into public.courses(slug,title,kind,landing_url,access_days,day_card_extra_days,automation_id,source_hash) values('month-health','Месяц здоровья','practicum','https://zamkovoi.yoga/m1',90,3,'48f08712-7146-54dc-ad58-e1dc6ae50879','0b721d01b4bf738b94185f76110b49f0721b4489248644e1d782597a3bbd8160') on conflict(slug) do update set title=excluded.title,source_hash=excluded.source_hash;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('85913963-0a67-5393-ab3c-8263e17fab9a','48f08712-7146-54dc-ad58-e1dc6ae50879','Урок 1',1,0,'{Месяц здоровья} Урок 1','{"ru":"{Месяц здоровья} Урок 1"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>Я рад, что вы решились в течение месяца целенаправленно поработать над своим здоровьем! Уроки этого практикума я проводил из Самарканда в формате прямых эфиров. Самарканд основан в VIII веке до н.э. (ровесник Рима) - это один из древнейших городов мира, перекресток Великого Шелкового пути, центр науки, культуры и торговли древнего мира. Занимаясь, вы сможете ощутить его интереснейшую энергетику. Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p>1. Расписание практик</p><p>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p>2. Техника безопасности</p><p>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p>3. Ответы на вопросы</p><p>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p>4. Ваши целенаправленные действия - условие изменений</p><p>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите укрепить здоровье. Так что выполняйте асаны, пранаяму, медитацию, питайтесь тем, что вас исцеляет, корректируйте режим дня, занимайтесь спортом, общайтесь с природой. Каждое своё действие совершайте с целью и с ощущением восстановления целостности и оздоравливания на уровне тела.</p><p>5. Первый урок</p><p>А теперь вы готовы перейти к первому уроку. В нём мы рассмотрим тему выработки здоровых привычек, и освоим технику суставной гимнастики, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Желаю вам плодотворных практик!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>Я рад, что вы решились в течение месяца целенаправленно поработать над своим здоровьем! Уроки этого практикума я проводил из Самарканда в формате прямых эфиров. Самарканд основан в VIII веке до н.э. (ровесник Рима) - это один из древнейших городов мира, перекресток Великого Шелкового пути, центр науки, культуры и торговли древнего мира. Занимаясь, вы сможете ощутить его интереснейшую энергетику. Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p>1. Расписание практик</p><p>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придёт вторая практика, ещё через неделю - третья, и через неделю - четвёртая. То есть в течение месяца, помимо вводного урока, вас ожидают четыре инереснейшие практики. Доступ к записям всех этих уроков сохранится у вас в течение трёх месяцев после окончания практикума. Тем не менее, я рекомендую вам проходить уроки не откладывая, так чтобы между практиками была неделя для внутренних трансформаций. Не увеличивайте интервалы между практиками, чтобы они не накапливались, как снежный ком. Наиболее эффективный темп занятий - одна практика в неделю. К тому-же имейте в виду, что первый урок посвящён тому, чтобы вы правильно сформулировали намерение на этот месяц, а также сами для себя определили небольшие дополнительные практики, которые будете выполнять каждый день в течение этого месяца.</p><p>2. Техника безопасности</p><p>Я забочусь о вашем здоровье и напоминаю, что только вы несёте ответственность за адекватность выполнения асан, пранаям и медитаций, вашим физическим возможностям и психическому состоянию. Важно понимать, что это онлайн занятия, и я не могу проконтролировать ваше состояние. Практикум ориентирован на людей со средним уровнем физической подготовки. Однако, у вас могут быть физические и психологические особенности. Пожалуйста, будьте внимательны к своему состоянию. Если вы почувствуете, что какая-то асана, которую я предлагаю выполнить, для вас преждевременна, выполните её не очень глубоко, на компромиссном уровне, или вовсе замените другой асаной - такой, которая приблизительно также включает тело, но проще для вас.</p><p>3. Ответы на вопросы</p><p>Каждую неделю (обычно по субботам) я провожу в Zoom групповые онлайн-консультации (вебинары), на которых мы общаемся, поддерживаем мотивацию, обсуждаем возникающие трудности и вопросы. Перед каждой такой консультацией я буду высылать вам письмо с указанием даты и времени её проведения, а также ссылкой для того, чтобы к ней присоединиться. То, что интересно вам, наверняка будет интересно и многим другим. Поэтому, обсуждение вопросов на групповых консультациях наиболее эффективно. Если случится так, что время консультации окажется вам неудобным, в этом случае пришлите ваши вопросы имейлом до её начала. Я отвечу на них на консультации, а вам пришлю ссылку на запись, чтобы вы могли посмотреть её в удобное вам время. Записи консультаций сохраняются в течение одной недели.</p><p>4. Ваши целенаправленные действия - условие изменений</p><p>Хотя это не программа подготовки космонавтов, всё-таки от вас потребуется некоторая дисциплина и целенаправленные действия. Так устроена эта жизнь, что для получения результатов нужно действовать. В том числе нужно действовать, если вы хотите укрепить здоровье. Так что выполняйте асаны, пранаяму, медитацию, питайтесь тем, что вас исцеляет, корректируйте режим дня, занимайтесь спортом, общайтесь с природой. Каждое своё действие совершайте с целью и с ощущением восстановления целостности и оздоравливания на уровне тела.</p><p>5. Первый урок</p><p>А теперь вы готовы перейти к первому уроку. В нём мы рассмотрим тему выработки здоровых привычек, и освоим технику суставной гимнастики, которую я рекомендую вам выполнять ежедневно в течение этого месяца. Урок довольно длинный, так как очень важно правильно сформулировать намерение и продумать небольшую практику на каждый день. Так как этот практикум я проводил в прямом эфире, вы услышите мои комментарии и ответы на задаваемые вопросы. Они помогут вам избежать распространённых ошибок.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Желаю вам плодотворных практик!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"month-health-01-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p>Я рад, что вы решились в течение месяца целенаправленно поработать над своим здоровьем! Уроки этого практикума я проводил из Самарканда в формате прямых эфиров. Самарканд основан в VIII веке до н.э. (ровесник Рима) - это один из древнейших городов мира, перекресток Великого Шелкового пути, центр науки, культуры и торговли древнего мира. Занимаясь, вы сможете ощутить его интереснейшую энергетику. Прочитайте это письмо полностью, чтобы понимать, что вас ожидает.</p><p>1. Расписание практик</p><p>Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». Чтобы его увидеть, при входе в Гармонизатор, укажите тот же ваш имейл, на который пришло данное письмо. Послезавтра вы получите второй урок - это будет наша первая совместная практика. Через неделю вам придё