insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('13caf28d-27ee-522d-9de2-232cc5a4f6e1','48f08712-7146-54dc-ad58-e1dc6ae50879','Урок 3',3,0,'{Месяц здоровья} Урок 3','{"ru":"{Месяц здоровья} Урок 3"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>Движемся дальше - в направлении здоровья и гармоничной первой чакры. На этом уроке мы рассмотрим несколько интересных и глубоких тем, касающихся природы заболеваний и выполнения асан, а также выполним глубокую практику исцеления.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>Движемся дальше - в направлении здоровья и гармоничной первой чакры. На этом уроке мы рассмотрим несколько интересных и глубоких тем, касающихся природы заболеваний и выполнения асан, а также выполним глубокую практику исцеления.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"month-health-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p>Движемся дальше - в направлении здоровья и гармоничной первой чакры. На этом уроке мы рассмотрим несколько интересных и глубоких тем, касающихся природы заболеваний и выполнения асан, а также выполним глубокую практику исцеления.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-health-03','month-health',3,7,'Урок 3','[{"type":"video","vimeoId":"1100532770"}]'::jsonb,'13caf28d-27ee-522d-9de2-232cc5a4f6e1') on conflict(id) do update set title=excluded.title,blocks=excluded.blocks,gap_days=excluded.gap_days;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('a521a3fb-4df6-555b-bd63-45dc0c629c98','48f08712-7146-54dc-ad58-e1dc6ae50879','Дополнительная практика',4,0,'{Месяц здоровья} Дополнительный урок','{"ru":"{Месяц здоровья} Дополнительный урок"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>Сюрприз! Чтобы поддержать вас в движении к здоровью, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию первой чакры.</p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>Сюрприз! Чтобы поддержать вас в движении к здоровью, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию первой чакры.</p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"month-health-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p>Сюрприз! Чтобы поддержать вас в движении к здоровью, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию первой чакры.</p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-health-04','month-health',4,3,'Дополнительная практика','[{"type":"video","vimeoId":"1133027002","practiceId":"cf3c9776-32c8-4c4b-a408-8a0f28843d59"}]'::jsonb,'a521a3fb-4df6-555b-bd63-45dc0c629c98') on conflict(id) do update set title=excluded.title,blocks=excluded.blocks,gap_days=excluded.gap_days;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('8b1dde07-02f9-514f-b3f8-7ccca9c8bb53','48f08712-7146-54dc-ad58-e1dc6ae50879','Урок 4',5,0,'{Месяц здоровья} Урок 4','{"ru":"{Месяц здоровья} Урок 4"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>Уже прошли три недели Месяца здоровья. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p>Урок 4 ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>Уже прошли три недели Месяца здоровья. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p>Урок 4 ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"month-health-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p>Уже прошли три недели Месяца здоровья. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p>Урок 4 ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-health-05','month-health',5,4,'Урок 4','[{"type":"video","vimeoId":"1100533053"}]'::jsonb,'8b1dde07-02f9-514f-b3f8-7ccca9c8bb53') on conflict(id) do update set title=excluded.title,blocks=excluded.blocks,gap_days=excluded.gap_days;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('28403f28-5a56-59f6-97d9-25e25b7cb2e8','48f08712-7146-54dc-ad58-e1dc6ae50879','Ещё один дополнительный урок',6,0,'{Месяц здоровья} Ещё один дополнительный урок','{"ru":"{Месяц здоровья} Ещё один дополнительный урок"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>И ещё один сюрприз! Люблю радовать :)</p><p>Высылаю вам ещё один дополнительный урок, направленный на гармонизацию первой чакры.</p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>И ещё один сюрприз! Люблю радовать :)</p><p>Высылаю вам ещё один дополнительный урок, направленный на гармонизацию первой чакры.</p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"month-health-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p>И ещё один сюрприз! Люблю радовать :)</p><p>Высылаю вам ещё один дополнительный урок, направленный на гармонизацию первой чакры.</p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-health-06','month-health',6,3,'Ещё один дополнительный урок','[{"type":"video","vimeoId":"1146135755","practiceId":"3ff9bbf1-692c-4647-aafd-f726fab2ac10"}]'::jsonb,'28403f28-5a56-59f6-97d9-25e25b7cb2e8') on conflict(id) do update set title=excluded.title,blocks=excluded.blocks,gap_days=excluded.gap_days;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('8a2246b4-dd65-5183-b59f-54459e808175','48f08712-7146-54dc-ad58-e1dc6ae50879','Урок 5',7,0,'{Месяц здоровья} Урок 5','{"ru":"{Месяц здоровья} Урок 5"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>Сегодня вас ожидает заключительный урок Месяца здоровья. В течение месяца вы направляли внимание на гармонизацию первой чакры, то есть на общее оздоравливание организма и выработку здоровых привычек. Что ж, это очень важная и мощная практика!</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Я уже много раз замечал, что когда практики переходят некий уровень глубины, им как будто кто-то (что-то) начинает препятствовать. Бывает, интернет пропадает, или в видео какие-то помехи появляются, или звук вдруг отключается, или какие-то посторонние шумы вмешиваются... В данном случае произошло всё перечисленное, кроме помех в изображении. К счастью, камера записала видео, и вы можете выполнить эту практику без препятствий.</p><p>Кстати, даже с публикацией этого видео возникли затруднения. Так как данный практикум я проводил в виде живых онлайн-занятий, я старался высылать участникам ссылку на запись прпошедшего занятия до окончания текущего дня. Так вот, после проведения данной практики, вечером в отеле отключился интернет. А видеофайл записи очень большой (всё-таки двухчасовая практика). Я решил подождать до утра, но утром мне сказали, что проблема с интернетом наблюдается по всему Самарканду, и она будет решена только через день - в понедельник. Когда же я попытался через мобильный интернет загрузить в Ютюб этот огромный видеофайл, то превысил лимит и загрузка прервалась. После этого я решил поехать к сотовому оператору, но во второй половине воскресенья все салоны связи оказались закрыты. Так вот - подобные приключения происходят довольно часто, когда мы переходим привычный для нас энергетический уровень :)</p><p>И, честно говоря, не всегда подобные препятствия необходимо столь упорно преодолевать. Если на вашей стороне при выполнении этой практики тоже возникнут затруднения, отложите её на несколько дней.</p><p>И я приглашаю вас продолжить совместное движение по пути йоги. Наиболее очевидными направлениями видятся следующие:<br>- Более интенсивно продолжить работу с первой чакрой, и записаться на месячный интенсив &quot;Здоровье&quot; - <a href="https://zamkovoi.yoga/i1">https://zamkovoi.yoga/i1</a><br>- Или направить внимание на мягкий и оздоравливающий вход в йогу, записавшись на месячный курс &quot;Йога и Здоровье&quot; - <a href="https://zamkovoi.yoga/yoga1">https://zamkovoi.yoga/yoga1</a><br>- Или перейти ко второй чакре, и записаться на практикум &quot;Месяц наслаждений&quot;, чтобы на месяц погрузиться в пространство расслабленности и удовольствия. Ведь вторая чакра включает в нас состояния весёлости, игривости, расслабленности, кайфушности, сексуальности... - <a href="https://zamkovoi.yoga/m2">https://zamkovoi.yoga/m2</a></p><p>Продолжайте практиковать, и будьте здоровы!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>Сегодня вас ожидает заключительный урок Месяца здоровья. В течение месяца вы направляли внимание на гармонизацию первой чакры, то есть на общее оздоравливание организма и выработку здоровых привычек. Что ж, это очень важная и мощная практика!</p><p>Урок ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Я уже много раз замечал, что когда практики переходят некий уровень глубины, им как будто кто-то (что-то) начинает препятствовать. Бывает, интернет пропадает, или в видео какие-то помехи появляются, или звук вдруг отключается, или какие-то посторонние шумы вмешиваются... В данном случае произошло всё перечисленное, кроме помех в изображении. К счастью, камера записала видео, и вы можете выполнить эту практику без препятствий.</p><p>Кстати, даже с публикацией этого видео возникли затруднения. Так как данный практикум я проводил в виде живых онлайн