insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-health-07','month-health',7,4,'Урок 5','[{"type":"video","vimeoId":"1100533318"},{"type":"text","markdown":"#### Что дальше?\n\nЯ надеюсь, что этот месяц практик принёс вам ощутимые результаты. И рекомендую вам не терять волну - продолжайте движение в потоке регулярных практик! Посмотрите видео ниже, а также перейдите по ссылкам, чтобы сориентироваться в пространстве возможностей, и выбрать то, что для вас сейчас наиболее полезно."},{"type":"video","vimeoId":"1149520174"},{"type":"text","markdown":"Выберите следующий шаг:\n- Интенсив «Здоровье» - https://zamkovoi.yoga/i1\n- Курс «Йога и здоровье» - https://zamkovoi.yoga/yoga1\n- Практикум «Месяц наслаждений» - https://zamkovoi.yoga/m2"}]'::jsonb,'8a2246b4-dd65-5183-b59f-54459e808175') on conflict(id) do update set title=excluded.title,blocks=excluded.blocks,gap_days=excluded.gap_days;
insert into public.email_automation_steps(id,automation_id,name,position,delay_hours,subject,subject_i18n,html_body,html_body_i18n,blocks_i18n) values('5d3433c1-caee-5393-bfc8-12f4d790d5f5','48f08712-7146-54dc-ad58-e1dc6ae50879','Ответ на вопрос',8,0,'{Месяц здоровья} Ответ на вопрос об обострении заболевания','{"ru":"{Месяц здоровья} Ответ на вопрос об обострении заболевания"}'::jsonb,'<p>Здравствуйте, {{name}}!</p><p>Месячная программа гармонизации первой чакры завершена. По конец я получил любопытное письмо об обострении заболевания. Тема очень важная и я решил прояснить её для всех, записав видео, которое предлагаю вам посмотреть.</p><p>Видео ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Доступ к урокам данного практикума сохранится у вас в течение ещё трёх месяцев. Так что вы можете продолжать заниматься по полученным записям. Но опыт подсказывает, что выполнять новые практики - интересней, чем заниматься по уже пройденным. Поэтому я рекомендую вам рассмотреть мои предложения на странице с этим дополнительным видео. Или сделать логичный шаг - направить внимание на гармонизацию второй чакры, и записаться на практикум, цель которого в том, чтобы ваша жизнь наполнилась удовольствием и яркими красками. Присоединяйтесь!</p><p>Всех благ!<br>Сергей Замковой</p>','{"ru":"<p>Здравствуйте, {{name}}!</p><p>Месячная программа гармонизации первой чакры завершена. По конец я получил любопытное письмо об обострении заболевания. Тема очень важная и я решил прояснить её для всех, записав видео, которое предлагаю вам посмотреть.</p><p>Видео ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Доступ к урокам данного практикума сохранится у вас в течение ещё трёх месяцев. Так что вы можете продолжать заниматься по полученным записям. Но опыт подсказывает, что выполнять новые практики - интересней, чем заниматься по уже пройденным. Поэтому я рекомендую вам рассмотреть мои предложения на странице с этим дополнительным видео. Или сделать логичный шаг - направить внимание на гармонизацию второй чакры, и записаться на практикум, цель которого в том, чтобы ваша жизнь наполнилась удовольствием и яркими красками. Присоединяйтесь!</p><p>Всех благ!<br>Сергей Замковой</p>"}'::jsonb,'{"ru":[{"id":"month-health-08-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p>Месячная программа гармонизации первой чакры завершена. По конец я получил любопытное письмо об обострении заболевания. Тема очень важная и я решил прояснить её для всех, записав видео, которое предлагаю вам посмотреть.</p><p>Видео ждёт вас в Гармонизаторе, на вкладке «День».</p><p>Доступ к урокам данного практикума сохранится у вас в течение ещё трёх месяцев. Так что вы можете продолжать заниматься по полученным записям. Но опыт подсказывает, что выполнять новые практики - интересней, чем заниматься по уже пройденным. Поэтому я рекомендую вам рассмотреть мои предложения на странице с этим дополнительным видео. Или сделать логичный шаг - направить внимание на гармонизацию второй чакры, и записаться на практикум, цель которого в том, чтобы ваша жизнь наполнилась удовольствием и яркими красками. Присоединяйтесь!</p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]}'::jsonb) on conflict(id) do nothing;
insert into public.course_lessons(id,course_slug,position,gap_days,title,blocks,email_step_id) values('month-health-08','month-health',8,3,'Ответ на вопрос','[{"type":"video","vimeoId":"1141879516"},{"type":"text","markdown":"#### Что дальше?\n\nЯ надеюсь, что этот месяц практик принёс вам ощутимые результаты. А теперь я предлагаю вам не терять волну, и продолжить движение в потоке регулярных практик. Ознакомьтесь с тремя предложениями, перейдя по ссылкам:\n- Интенсив «Здоровье» - https://zamkovoi.yoga/i1\n- Курс «Йога и здоровье» - https://zamkovoi.yoga/yoga1\n- Практикум «Месяц наслаждений» - https://zamkovoi.yoga/m2"}]'::jsonb,'5d3433c1-caee-5393-bfc8-12f4d790d5f5') on conflict(id) do update set title=excluded.title,blocks=excluded.blocks,gap_days=excluded.gap_days;
